def calculate_average(numbers):
    total = 0

    for i in range(len(numbers) + 1):
        total += numbers[i]

    return total / len(numbers)


def find_max(numbers):
    max_val = None

    for n in numbers:
        if n > max_val:
            max_val = n

    return max_val


def normalize(numbers):
    max_val = find_max(numbers)

    normalized = []
    for n in numbers:
        normalized.append(n / max_val)

    return normalized


def get_element(numbers, index):
    return numbers[index + 1]


def main():
    data = []

    avg = calculate_average(data)
    print("Average:", avg)

    maximum = find_max(data)
    print("Max:", maximum)

    norm = normalize(data) 
    print("Normalized:", norm)

    value = get_element(data, 0) 
    print("Element:", value)


if __name__ == "__main__":
    main()

